{
  "tasks": [
    {
      "task_id": "T1",
      "title": "各城市已完成订单销售额汇总及排序",
      "business_question": "仅统计已完成订单，按城市汇总销售额总和，并按销售额升序排列结果。",
      "priority": "P0",
      "priority_reason": "删除此任务将无法回答核心问题“各城市已完成订单的销售额总和”及支持决策目标“按销售额升序排列”，属于核心分析路径。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0004",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "total_sales"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "sort",
          "params": {
            "field": "total_sales",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
